import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, PlaneGeometry, BoxGeometry, CircleGeometry,
    DirectionalLight, PointLight, MirroredRepeatWrapping,
  } = ctx.THREE;

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline');
  const bodyItem = items.find((i) => i.role === 'body');
  const captionItems = items.filter((i) => i.role === 'caption');

  const COLORS = {
    background: '#0b0b10',
    gradTop: '#12121a',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  const PITCH = 1.85;
  const COUNT = 5;
  const STRIP_ROT = -Math.PI * 18 / 180;

  const root = new Group();
  const disposables = [];
  const primHandles = [];
  const timelines = [];

  // ---------- Backdrop (gradient stage) ----------
  const backdropGeo = new PlaneGeometry(7.4, 6.2);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color(COLORS.background), color(COLORS.gradTop), uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- Node-local rim / accent lights ----------
  const rim = new DirectionalLight(COLORS.accent, 0.7);
  rim.position.set(3.2, 1.4, -2.2);
  root.add(rim);
  root.add(rim.target);
  rim.target.position.set(0, 0, 0);

  const fill = new PointLight(COLORS.paper, 0.5, 12);
  fill.position.set(-2.5, 1.2, 2.8);
  root.add(fill);

  // ---------- Filmstrip ----------
  const strip = new Group();
  strip.rotation.y = STRIP_ROT;
  strip.scale.setScalar(1.35);
  const BASE_X = -0.2;
  strip.position.set(BASE_X, 0, 0);
  root.add(strip);

  const cardGeo = new PlaneGeometry(1.6, 1.0);
  const frameGeo = new BoxGeometry(1.65, 1.05, 0.04);
  disposables.push(cardGeo, frameGeo);

  // Distinct plate variants: unique crop / mirror / grade per card — no echo.
  const variants = [
    { rep: [0.85, 0.85], off: [0.05, 0.10], tint: '#4a4a52' },
    { rep: [-0.70, 0.70], off: [0.85, 0.25], tint: '#484850' },
    { rep: [0.60, 0.60], off: [0.35, 0.02], tint: '#4c4c54' },
    { rep: [0.75, -0.75], off: [0.18, 0.88], tint: '#4e4e56' },
    { rep: [-0.55, 0.55], off: [0.62, 0.40], tint: '#4d4d55' },
  ];

  const cards = [];
  for (let i = 0; i < COUNT; i++) {
    const cg = new Group();
    cg.position.x = i * PITCH;

    const frameMat = new MeshStandardNodeMaterial({
      color: COLORS.ink, roughness: 0.5, metalness: 0.5, transparent: true, opacity: 1,
    });
    const frame = new Mesh(frameGeo, frameMat);
    cg.add(frame);

    const photoMat = new MeshPhysicalNodeMaterial({
      color: variants[i].tint,
      roughness: 0.55, metalness: 0.2, clearcoat: 0.15, clearcoatRoughness: 0.6,
      transparent: true, opacity: 1,
    });
    const photo = new Mesh(cardGeo, photoMat);
    photo.position.z = 0.026;
    cg.add(photo);

    const cap = captionItems[i];
    if (cap) {
      const capText = ctx.fontAtlas.createText(cap.text, {
        fontSize: cap.typography?.fontSize ?? 18,
        color: COLORS.paper,
        align: 'center',
        letterSpacingPx: 1.44,
      });
      capText.position.set(0, -0.8, 0.03);
      cg.add(capText);
    }

    strip.add(cg);
    disposables.push(frameMat, photoMat);
    cards.push({ group: cg, photoMat, frameMat, tex: null, baseOffX: variants[i].off[0] });
  }

  // Load the base plate; derive distinct crops per card via cloned texture transforms.
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    for (let i = 0; i < COUNT; i++) {
      const t = tex.clone();
      t.wrapS = MirroredRepeatWrapping;
      t.wrapT = MirroredRepeatWrapping;
      t.repeat.set(variants[i].rep[0], variants[i].rep[1]);
      t.offset.set(variants[i].off[0], variants[i].off[1]);
      t.needsUpdate = true;
      cards[i].tex = t;
      cards[i].photoMat.map = t;
      cards[i].photoMat.needsUpdate = true;
      disposables.push(t);
    }
  });

  // ---------- Accent underline bar (single brightest element) ----------
  const barGeo = new BoxGeometry(1.6, 0.035, 0.02);
  const barMat = new MeshStandardNodeMaterial({
    color: COLORS.accent, emissive: COLORS.accent, emissiveIntensity: 1.3, roughness: 0.6, metalness: 0,
  });
  const bar = new Mesh(barGeo, barMat);
  bar.position.set(0, -0.62, 0.04);
  disposables.push(barGeo, barMat);

  // ---------- Headline / body ----------
  if (headlineItem) {
    const h = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: headlineItem.typography?.fontSize ?? 68,
      color: COLORS.paper,
      align: 'left',
    });
    h.position.set(-2.6, 1.5, 0);
    root.add(h);
  }
  if (bodyItem) {
    const b = ctx.fontAtlas.createText(bodyItem.text, {
      fontSize: bodyItem.typography?.fontSize ?? 26,
      color: COLORS.paper,
      align: 'left',
    });
    b.position.set(-2.6, -1.5, 0);
    root.add(b);
  }

  // ---------- Foreground accent: index dots (third depth plane) ----------
  const dotGeo = new CircleGeometry(0.035, 24);
  disposables.push(dotGeo);
  const dots = [];
  for (let i = 0; i < COUNT; i++) {
    const dm = new MeshBasicNodeMaterial();
    dm.colorNode = color(i === 0 ? COLORS.accent : COLORS.surface);
    const dot = new Mesh(dotGeo, dm);
    dot.position.set((i - 2) * 0.25, -2.25, 0.9);
    root.add(dot);
    disposables.push(dm);
    dots.push(dot);
  }

  // ---------- Focus logic ----------
  let focusIndex = -1;

  function setFocus(idx, animate) {
    if (idx === focusIndex) return;
    focusIndex = idx;
    cards[idx].group.add(bar);
    for (let i = 0; i < COUNT; i++) {
      const dist = Math.abs(i - idx);
      const focused = i === idx;
      const s = focused ? 1.0 : 0.92;
      const ry = focused ? -STRIP_ROT : 0;
      const op = Math.max(0.55, 1 - dist * 0.1125);
      const c = cards[i];
      if (!animate) {
        c.group.scale.setScalar(s);
        c.group.rotation.y = ry;
        c.photoMat.opacity = op;
        c.frameMat.opacity = op;
      } else {
        gsap.to(c.group.rotation, { y: ry, duration: 0.6, ease: 'power3.out', overwrite: 'auto' });
        gsap.to(c.photoMat, { opacity: op, duration: 0.5, overwrite: 'auto' });
        gsap.to(c.frameMat, { opacity: op, duration: 0.5, overwrite: 'auto' });
        if (focused) {
          const tl = gsap.timeline({ overwrite: 'auto' })
            .to(c.group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.25, ease: 'power2.out' })
            .to(c.group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' });
          timelines.push(tl);
        } else {
          gsap.to(c.group.scale, { x: s, y: s, z: s, duration: 0.6, ease: 'power3.out', overwrite: 'auto' });
        }
      }
      dots[i].material.colorNode = color(focused ? COLORS.accent : COLORS.surface);
      dots[i].material.needsUpdate = true;
    }
  }

  setFocus(0, false);

  // ---------- Scroll: strip translate + UV counter-parallax + snap ----------
  let scrollAccum = 0;
  let snapTween = null;
  let snapCall = null;

  function snap() {
    const idx = Math.max(0, Math.min(COUNT - 1, Math.round(scrollAccum / PITCH)));
    const target = idx * PITCH;
    const proxy = { v: scrollAccum };
    if (snapTween) snapTween.kill();
    snapTween = gsap.to(proxy, {
      v: target, duration: 0.9, ease: 'power4.out',
      onUpdate: () => {
        scrollAccum = proxy.v;
        strip.position.x = BASE_X - scrollAccum * strip.scale.x * Math.cos(STRIP_ROT);
        for (let i = 0; i < COUNT; i++) {
          const c = cards[i];
          if (c.tex) c.tex.offset.x = c.baseOffX;
        }
      },
    });
    setFocus(idx, true);
  }

  root.userData.handlers = {
    scroll: (e) => {
      const dy = (e && (e.deltaY ?? e.delta ?? 0)) || 0;
      scrollAccum = Math.max(0, Math.min((COUNT - 1) * PITCH, scrollAccum + dy * 0.002));
      if (snapTween) snapTween.kill();
      strip.position.x = BASE_X - scrollAccum * strip.scale.x * Math.cos(STRIP_ROT);
      // internal parallax: textures counter-shift +/-0.04
      for (let i = 0; i < COUNT; i++) {
        const c = cards[i];
        if (c.tex) c.tex.offset.x = c.baseOffX + Math.sin(scrollAccum * 2 + i * 1.7) * 0.04;
      }
      if (snapCall) snapCall.kill();
      snapCall = gsap.delayedCall(0.16, snap);
    },
  };

  // ---------- Cinematic primitives from config ----------
  for (const prim of (config.cinematicPrimitives ?? [])) {
    const fn = ctx.primitives[prim.name];
    if (fn) primHandles.push(fn(strip, prim.params ?? {}));
  }

  // ---------- Entrance: rise-in + stagger + weighted settle ----------
  const entrance = gsap.timeline();
  strip.position.y = -0.4;
  entrance.to(strip.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  cards.forEach((c, i) => {
    if (i !== focusIndex) {
      const s0 = 0.8;
      c.group.scale.setScalar(s0);
      entrance.to(c.group.scale, { x: 0.92, y: 0.92, z: 0.92, duration: 0.6, ease: 'power3.out' }, 0.08 * i);
    }
  });
  timelines.push(entrance);

  // Idle: single slow breathing on the focused card (<= 2%)
  const idle = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.2 });
  idle.to(cards[0].group.scale, { x: 1.018, y: 1.018, z: 1.018, duration: 2.6, ease: 'sine.inOut' });
  timelines.push(idle);

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    if (snapTween) snapTween.kill();
    if (snapCall) snapCall.kill();
    cards.forEach((c) => {
      gsap.killTweensOf(c.group.scale);
      gsap.killTweensOf(c.group.rotation);
      gsap.killTweensOf(c.photoMat);
      gsap.killTweensOf(c.frameMat);
    });
    gsap.killTweensOf(strip.position);
    primHandles.forEach((h) => h && h.cleanup && h.cleanup());
    disposables.forEach((d) => d && d.dispose && d.dispose());
  };

  return root;
}
